import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.D_TdfPur.js";const o="/michi-chat/screenshots/analytics.png",i="/michi-chat/screenshots/accounts.png",r="/michi-chat/screenshots/conversations.png",h="/michi-chat/screenshots/conversation-detail.png",c="/michi-chat/screenshots/unanswered.png",d="/michi-chat/screenshots/usage.png",b=JSON.parse('{"title":"Running it day to day","description":"Running a michi-chat assistant in ten minutes a week: analytics, staff accounts, reading conversations, fixing unanswered questions, Slack pings.","frontmatter":{"description":"Running a michi-chat assistant in ten minutes a week: analytics, staff accounts, reading conversations, fixing unanswered questions, Slack pings.","head":[["link",{"rel":"canonical","href":"https://beany-vu.github.io/michi-chat/owner/day-to-day"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"michi-chat"}],["meta",{"property":"og:title","content":"Running it day to day"}],["meta",{"property":"og:description","content":"Running a michi-chat assistant in ten minutes a week: analytics, staff accounts, reading conversations, fixing unanswered questions, Slack pings."}],["meta",{"property":"og:url","content":"https://beany-vu.github.io/michi-chat/owner/day-to-day"}],["meta",{"property":"og:image","content":"https://beany-vu.github.io/michi-chat/og-card.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"michi-chat: a chat assistant platform for small businesses, with the Michi cat crest"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Running it day to day"}],["meta",{"name":"twitter:description","content":"Running a michi-chat assistant in ten minutes a week: analytics, staff accounts, reading conversations, fixing unanswered questions, Slack pings."}],["meta",{"name":"twitter:image","content":"https://beany-vu.github.io/michi-chat/og-card.png"}]]},"headers":[],"relativePath":"owner/day-to-day.md","filePath":"owner/day-to-day.md"}'),p={name:"owner/day-to-day.md"};function l(g,t,u,m,w,y){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="running-it-day-to-day" tabindex="-1">Running it day to day <a class="header-anchor" href="#running-it-day-to-day" aria-label="Permalink to &quot;Running it day to day&quot;">​</a></h1><p>Ten minutes a week, honestly.</p><h2 id="see-what-matters-at-a-glance" tabindex="-1">See what matters at a glance <a class="header-anchor" href="#see-what-matters-at-a-glance" aria-label="Permalink to &quot;See what matters at a glance&quot;">​</a></h2><p><strong>Tenant → Analytics</strong> turns the raw data into decisions: messages per day, which capabilities visitors reach for, the exact knowledge-base searches they triggered (a frequent query with a weak answer is your next document to write), busy hours, and where conversations come from. Country-level location appears when the platform runs behind Cloudflare - IPs are never stored.</p><p>The &quot;What visitors reach for&quot; bars name the lookups by their function id; under the bars, each one is explained in plain words - what it does, what goes in, what comes back - so you never need the code to understand what the assistant did.</p><p><img src="'+o+'" alt="The analytics page"></p><h2 id="let-staff-help" tabindex="-1">Let staff help <a class="header-anchor" href="#let-staff-help" aria-label="Permalink to &quot;Let staff help&quot;">​</a></h2><p><strong>Accounts</strong> (owner only) creates staff logins: staff can read conversations and usage and maintain the knowledge base, but cannot touch tenants, embed keys, or settings. The day-to-day loop below is exactly what staff accounts are for.</p><p>Staff see only the tenants you tick for them - on the form when you create the account, or later with the checkboxes on their row and that row&#39;s <strong>Save</strong>. A staff account with nothing ticked sees an empty admin until you assign it, so a new login is safe by default. Changes apply on the account&#39;s next page load, no re-login needed. To try it yourself, create a test staff account, tick one tenant, sign out and log in as it; <strong>Disable</strong> the row when you are done.</p><p><img src="'+i+'" alt="The accounts page with per-tenant checkboxes on a staff row"></p><h2 id="read-what-customers-ask" tabindex="-1">Read what customers ask <a class="header-anchor" href="#read-what-customers-ask" aria-label="Permalink to &quot;Read what customers ask&quot;">​</a></h2><p><strong>Conversations</strong> shows every chat, newest first. This is the most valuable page in the product: it&#39;s a diary of what your customers want to know.</p><p><img src="'+r+'" alt="The conversations list"></p><p>Open one to read the full exchange, including which lookups the assistant used:</p><p><img src="'+h+'" alt="A single conversation transcript"></p><p>Suspicious chats are marked with a 🚩 (the platform flags prompt-injection bait and <code>/command</code> probes on its own; you can flag or unflag any conversation by hand from its transcript), and the <strong>🚩 Flagged</strong> chip shows only those.</p><h2 id="fix-a-wrong-or-missing-answer" tabindex="-1">Fix a wrong or missing answer <a class="header-anchor" href="#fix-a-wrong-or-missing-answer" aria-label="Permalink to &quot;Fix a wrong or missing answer&quot;">​</a></h2><p>When you spot the assistant saying &quot;I don&#39;t know&quot; to something it <em>should</em> know - or being vague - the fix is always the same: open <strong>Knowledge base</strong>, add or sharpen the fact, save. The very next question uses the new answer. No restarts, no waiting.</p><p><strong>Unanswered</strong> does the spotting for you: it lists every turn where the assistant admitted it didn&#39;t know, with the visitor question that caused it and an <strong>Add fact</strong> shortcut. With several businesses on one instance, the tenant chips at the top narrow the list to one of them. Working that list weekly is the highest-leverage habit in the admin - every row you fix is a question answered properly forever after.</p><p><img src="'+c+'" alt="The unanswered report with tenant chips"></p><h2 id="watch-the-numbers" tabindex="-1">Watch the numbers <a class="header-anchor" href="#watch-the-numbers" aria-label="Permalink to &quot;Watch the numbers&quot;">​</a></h2><p><strong>Usage</strong> shows messages per day per business, so you can see quiet weeks, busy launches, and how close you run to your daily cap.</p><p><img src="'+d+'" alt="The usage page"></p><p>If you hit the cap on normal days, raise it in the settings; if you hit it because something hammered the chat, the cap did exactly its job.</p><h2 id="get-pinged-when-it-matters" tabindex="-1">Get pinged when it matters <a class="header-anchor" href="#get-pinged-when-it-matters" aria-label="Permalink to &quot;Get pinged when it matters&quot;">​</a></h2><p>With a Slack webhook configured, each new conversation lands in your Slack as it starts, with the visitor&#39;s first message - nice for hopping in personally during opening hours. You&#39;ll also get one alert if the daily cap is reached.</p><p>Never made a webhook? It&#39;s free and takes about two minutes:</p><ol><li>Go to <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">api.slack.com/apps</a> and click <strong>Create New App</strong> → <em>From scratch</em>. Any name (&quot;Cafe pings&quot; is fine), pick your workspace.</li><li>In the app&#39;s menu, open <strong>Incoming Webhooks</strong> and switch the toggle on.</li><li>Click <strong>Add New Webhook to Workspace</strong> and choose the channel that should receive the pings (a private <code>#cafe-chat</code> channel works well).</li><li>Copy the URL Slack shows you - it starts with <code>https://hooks.slack.com/services/</code> - and paste it into <strong>Tenant → Notifications</strong>. Save, and the next conversation pings you.</li></ol><p>Only that exact kind of URL is accepted; anything else is rejected on purpose (it&#39;s a security boundary). To stop the pings, clear the field; to change channels, make a new webhook and paste the new URL.</p><h2 id="the-habit-that-compounds" tabindex="-1">The habit that compounds <a class="header-anchor" href="#the-habit-that-compounds" aria-label="Permalink to &quot;The habit that compounds&quot;">​</a></h2><p>Once a week, skim the conversations and add one knowledge-base fact for anything the assistant fumbled. After a month of that, it answers like your best barista.</p>',31)])])}const k=e(p,[["render",l]]);export{b as __pageData,k as default};
